<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\TenantLoginProviderSamlIdpIdpCertVO;

final class TenantLoginProviderSamlIdpIdpCertVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = 'store://bin';
        $ref = TenantLoginProviderSamlIdpIdpCertVO::from($value);
        $this->assertEquals('bin', $ref->value());
        $other = TenantLoginProviderSamlIdpIdpCertVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TenantLoginProviderSamlIdpIdpCertVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TenantLoginProviderSamlIdpIdpCertVO::tryFrom(1, $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TenantLoginProviderSamlIdpIdpCertVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TenantLoginProviderSamlIdpIdpCertVO::from('store://bin');
        $same = TenantLoginProviderSamlIdpIdpCertVO::from('store://bin');
        $other = TenantLoginProviderSamlIdpIdpCertVO::from('store://obin');
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = TenantLoginProviderSamlIdpIdpCertVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = TenantLoginProviderSamlIdpIdpCertVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
    public function test_cypher_builders(): void
    {
        $errors = new ConstraintFailList();
        $temp = TenantLoginProviderSamlIdpIdpCertVO::fromTemporal('tempus');
        $this->assertEquals('tempus', $temp->value());
        $temp = TenantLoginProviderSamlIdpIdpCertVO::tryFromTemporal('tempus', $errors);
        $this->assertEquals('tempus', $temp->value());
        $this->assertTrue($errors->isEmpty());
        $external = TenantLoginProviderSamlIdpIdpCertVO::fromStored('http://www.php.net/');
        $this->assertEquals('http://www.php.net/', $external->value());
        $external = TenantLoginProviderSamlIdpIdpCertVO::tryFromStored('http://www.php.net/', $errors);
        $this->assertEquals('http://www.php.net/', $external->value());
        $this->assertTrue($errors->isEmpty());
        $internal = TenantLoginProviderSamlIdpIdpCertVO::fromStored('none');
        $this->assertEquals('none', $internal->value());
        $external = TenantLoginProviderSamlIdpIdpCertVO::tryFromStored('none', $errors);
        $this->assertEquals('none', $internal->value());
        $this->assertTrue($errors->isEmpty());
    }
    public function test_invalid_file_schmea(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        TenantLoginProviderSamlIdpIdpCertVO::from('none');
    }
}
